    'contact_form_success': { en: 'Thank you! Your message has been sent successfully.', ko: '감사합니다! 메시지가 성공적으로 전송되었습니다.', ar: 'شكراً لك! تم إرسال رسالتك بنجاح.', ja: 'ありがとうございます！メッセージが正常に送信されました。' },
    'contact_form_error': { en: 'Something went wrong. Please try again or email us directly.', ko: '문제가 발생했습니다. 다시 시도하거나 이메일로 직접 문의하십시오.', ar: 'حدث خطأ. يرجى المحاولة مرة أخرى أو مراسلتنا عبر البريد الإلكتروني.', ja: '問題が発生しました。もう一度お試しいただくか、メールで直接お問い合わせください。' },
