    /* SHISHA PAGE */
    'shisha_heading1': { en: 'Coconut Shisha', ko: '코코넛 시샤', ar: 'شيشة جوز الهند', ja: 'ココナッツシシャ' },
    'shisha_heading2': { en: 'Charcoal Briquette', ko: '숯 브리켓', ar: 'فحم بوريت', ja: 'チャコールブリケット' },
    'shisha_desc': { en: 'What makes coconut shell charcoal briquettes unique is how they burn: a naturally sourced by-product of cutting down trees, it creates a sustainable alternative to traditional wood charcoal. Coconut Shell Charcoal Briquettes burn significantly hotter, last longer, and burn behind any little ash. More importantly, they burn completely clean without smoke, sparks, or harmful chemicals, making them a safe and environmentally friendly choice for shisha, barbeques, and various industrial applications.', ko: '코코넛 쉘 숯 브리켓을 고유하게 만드는 것은 연소 방식입니다: 나무를 베는 과정에서 자연적으로 발생하는 부산물로, 전통적인 목재 숯에 대한 지속 가능한 대안을 만듭니다. 코코넛 쉘 숯 브리켓은 상당히 더 뜨겁게 타고, 더 오래 지속되며, 적은 재를 남깁니다. 더 중요한 것은 연기, 스파크 또는 유해 화학 물질 없이 완전히 깨끗하게 타기 때문에 시샤, 바비큐 및 다양한 산업 응용 분야에 안전하고 환경 친화적인 선택이라는 것입니다.', ar: 'ما يجعل فحم البوريت من قشور جوز الهند فريدة هو طريقة احتراقها: منتج ثانوي طبيعي من قطع الأشجار، يخلق بديلاً مستداماً لفحم الخشب التقليدي. تحترق بوريت قشور جوز الهند بشكل أحر بكثير، وتدوم أطول، وتحترق دون أي رماد تقريباً.', ja: 'ココナッツシェルチャコールブリケットをユニークにしているのは、その燃焼方法です。树木を伐採する過程で自然に発生する副産物であり、従来の木炭に対する持続可能な代替品を生み出します。ココナッツシェルチャコールブリケットはかなり高温で燃え、長持ちし、最小限の灰を残します。より重要なのは、煙、スパーク、有害化学物質なしで完全にクリーンに燃焼するため、シシャ、BBQ、 various 工業用途に安全で環境に優しい選択肢であること。' },
    'shisha_spec_title': { en: 'Specification', ko: '사양', ar: 'المواصفات', ja: '仕様' },
    'shisha_spec_sub': { en: 'Choose the right charcoal grade for your business needs.', ko: '비즈니스 요구에 맞는 올바른 숯 등급을 선택하십시오.', ar: 'اختر درجة الفحم المناسبة لاحتياجات عملك.', ja: 'ビジネスニーズに合ったチャコールグレードを選択してください。' },
    'shisha_grade1': { en: 'Platinum (AAA)', ko: '플래티넘 (AAA)', ar: 'بلاتين (AAA)', ja: 'プラチナ（AAA）' },
    'shisha_grade2': { en: 'Super Premium (AA)', ko: '슈퍼 프리미엄 (AA)', ar: 'super ممتاز (AA)', ja: 'スーパープレミアム（AA）' },
    'shisha_grade3': { en: 'Premium (A)', ko: '프리미엄 (A)', ar: 'ممتاز (A)', ja: 'プレミアム（A）' },
