    /* SHISHA PACKAGING */
    'shisha_pack1_tag': { en: 'Industrial Bulk Packaging', ko: '산업용 벌크 포장', ar: 'تغليف بالجملة الصناعي', ja: '産業用バルクパッケージ' },
    'shisha_pack1_desc': { en: 'An optimized solution for large-scale shipments. This features only inner plastic packed directly into secure master boxes, maximizing container space and reducing total freight costs. It is the ideal high-performance, economical choice for businesses requiring high-volume throughput.', ko: '대규모 배송을 위한 최적화된 솔루션. 안전한 마스터 박스에 직접 포장된 내부 플라스틱만 사용하여 컨테이너 공간을 최대화하고 총 운송 비용을 절감합니다. 대량 처리가 필요한 기업에 이상적인 고성능 경제적 선택입니다.', ar: 'حلول محسّنة للشحن واسع النطاق. تتضمن فقط بلاستيك داخلي معبأ مباشرة في صناديق رئيسية آمنة.', ja: '大規模輸送のための最適化されたソリューション。安全なマスターボックスに直接梱包された内部プラスチックのみを使用し、コンテナスペースを最大化し、総輸送コストを削減します。' },
    'shisha_pack2_tag': { en: 'Retail-Ready Solutions', ko: '소매 준비 솔루션', ar: 'حلول جاهزة للبيع بالتجزئة', ja: '小売準備完了ソリューション' },
    'shisha_pack2_desc': { en: 'Designed for private label excellence, this end-to-end packaging solution includes high-quality inner plastic, custom inner boxes, and durable master cartons to ensure your products arrive in pristine condition.', ko: '프라이빗 라벨 우수성을 위해 설계된 end-to-end 포장 솔루션으로, 고품질 내부 플라스틱, 맞춤형 내부 상자 및 튼튼한 마스터 카톤이 포함되어 제품이 최상의 상태로 도착하도록 보장합니다.', ar: 'مصممة لتميز العلامة الخاصة، تتضمن هذه الحل التغليفي الشامل بلاستيك داخلي عالي الجودة وصناديق داخلية مخصصة وكراتين رئيسية متينة.', ja: 'プライベートラベルの卓越性のために設計された、エンドツーエンドのパッケージソリューション。高品質な内部プラスチック、カスタムインナーボックス、耐久性のあるマスターカートンが含まれ、製品が完全な状態で到着することを保証します。' },
    'shisha_pack3_tag': { en: 'Wholesale Distribution Packaging', ko: '도매 유통 포장', ar: 'تغليف التوزيع بالجملة', ja: '卸売流通パッケージ' },
    'shisha_pack3_desc': { en: 'Best suited for high-volume trade, this packaging model features robust inner plastic and master carton only. By focusing on essential protection, we eliminate unnecessary material costs, providing a practical and reliable solution that excels in high-speed handling and international transit.', ko: '대량 거래에 가장 적합한이 포장 모델은 견고한 내부 플라스틱과 마스터 카톤만 사용합니다. 필수적인 보호에 초점을 맞추어 불필요한 재료 비용을 제거하고 고속 처리 및 국제 운송에서 뛰어난 실용적이고 신뢰할 수 있는 솔루션을 제공합니다.', ar: 'الأفضل للتجارة واسعة النطاق، يتضمن هذا النموذج التغليفي بلاستيك داخلي متين وكراتين رئيسية فقط.', ja: '大規模取引に最適なこのパッケージモデルは、堅牢な内部プラスチックとマスターカートンのみを使用します。必須の保護に焦点を当て、不要な材料コストを排除し、ハイスピード処理と国際輸送で優れた実用的で信頼性の高いソリューションを提供します。' },

    /* BBQ SHAPESIZE */
    'bbq_hexagonal': { en: 'Hexagonal', ko: '육각형', ar: 'سداسي', ja: '六角形' },
